// src/App.js
import React from "react";
import GoogleWalletIntegration from "./components/GoogleWalletIntegration";
import "./styles/App.css";
import logo from "./assets/logoHDI.png"; // Importar logo desde src/assets/

function App() {
  return (
    <div className="App">
      <div className="header">
        <img src={logo} alt="HDI Seguros México" className="logo" />
        <h1>Generador de Tickets para Eventos</h1>
      </div>
      <div className="container">
        <GoogleWalletIntegration />
      </div>
    </div>
  );
}

export default App;
